from pathlib import Path
import base64

def dec(s): return base64.b64decode(s).decode('utf-8')

def replace_once(path, old64, new64, label):
    p = Path(path)
    src = p.read_text(encoding='utf-8')
    old = dec(old64); new = dec(new64)
    if new in src:
        return
    if old not in src:
        raise SystemExit(f'{label}: anchor not found')
    p.write_text(src.replace(old, new, 1), encoding='utf-8', newline='\n')

